import argparse,ctypes,torch,torch.distributed as dist
import torch.nn.functional as F
from megatron.core import parallel_state

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--so',required=True); a=ap.parse_args()
    rank=int(__import__('os').environ['RANK']); world=int(__import__('os').environ['WORLD_SIZE']); local=int(__import__('os').environ['LOCAL_RANK']); torch.cuda.set_device(local); dist.init_process_group('nccl',rank=rank,world_size=world); parallel_state.initialize_model_parallel(tensor_model_parallel_size=world,pipeline_model_parallel_size=1)
    lib=ctypes.CDLL(a.so); lib.local_max_fp16_stream.restype=ctypes.c_int; lib.local_prepare_fp16_stream.restype=ctypes.c_int
    rows=32; V=64; lv=V//world; torch.manual_seed(700+rows); full=torch.randn(rows,V,device='cuda',dtype=torch.float16); target=torch.randint(0,V,(rows,),device='cuda',dtype=torch.long); x=full[:,rank*lv:(rank+1)*lv].contiguous(); stream=torch.cuda.current_stream()
    lm=torch.empty(rows,device='cuda',dtype=torch.float32); rc=lib.local_max_fp16_stream(ctypes.c_void_p(x.data_ptr()),ctypes.c_void_p(lm.data_ptr()),rows,lv,ctypes.c_void_p(stream.cuda_stream)); torch.cuda.synchronize(); dist.all_reduce(lm,op=dist.ReduceOp.MAX); torch.cuda.synchronize()
    pred=torch.empty(rows,device='cuda',dtype=torch.float32); den=torch.empty_like(pred); ex=torch.empty(rows,lv,device='cuda',dtype=torch.float32); mask=torch.empty(rows*lv,device='cuda',dtype=torch.uint8); tl=torch.empty(rows,device='cuda',dtype=torch.long)
    rc2=lib.local_prepare_fp16_stream(ctypes.c_void_p(x.data_ptr()),ctypes.c_void_p(target.data_ptr()),ctypes.c_void_p(lm.data_ptr()),ctypes.c_void_p(pred.data_ptr()),ctypes.c_void_p(den.data_ptr()),ctypes.c_void_p(ex.data_ptr()),ctypes.c_void_p(mask.data_ptr()),ctypes.c_void_p(tl.data_ptr()),rows,lv,rank,ctypes.c_void_p(stream.cuda_stream)); torch.cuda.synchronize(); dist.all_reduce(pred); dist.all_reduce(den); torch.cuda.synchronize(); loss=torch.log(den)-pred; ref=F.cross_entropy(full,target,reduction='none'); err=(loss-ref).abs().max(); dist.all_reduce(err,op=dist.ReduceOp.MAX); soft=ex/den[:,None]; expected=F.softmax(full.float(),dim=-1)[:,rank*lv:(rank+1)*lv]; ge=(soft-expected).abs().max(); dist.all_reduce(ge,op=dist.ReduceOp.MAX); fullg=full.float().detach().clone().requires_grad_(); F.cross_entropy(fullg,target,reduction='sum').backward(); gg=fullg.grad[:,rank*lv:(rank+1)*lv]; sg=soft.clone(); owned=(target>=rank*lv)&(target<(rank+1)*lv); idx=(target-rank*lv).clamp(0,lv-1); sg[torch.arange(rows,device='cuda'),idx]-=owned.float(); graderr=(sg-gg).abs().max(); dist.all_reduce(graderr,op=dist.ReduceOp.MAX); torch.cuda.synchronize(); print({'rank':rank,'rc':rc,'rc2':rc2,'loss_max_abs':float(err),'softmax_max_abs':float(ge),'grad_max_abs':float(graderr),'pass':bool(float(err)<0.01 and float(ge)<0.01 and float(graderr)<0.01)},flush=True); parallel_state.destroy_model_parallel(); dist.barrier(); dist.destroy_process_group()
if __name__=='__main__': main()
